// Curves for the path components: dense polylines with arc length, so items can be placed by distance along the line.

import type { V3 } from './kit.js';

export type PathShape = 'wave' | 'triangle' | 'square' | 'infinity';
export const PATH_SHAPES: PathShape[] = ['wave', 'triangle', 'square', 'infinity'];

export interface Curve {
  pts: V3[];
  /** Cumulative arc length at each point. */
  len: number[];
  total: number;
  closed: boolean;
}

const chaikin = (pts: V3[], times: number): V3[] => {
  let p = pts;
  for (let t = 0; t < times; t += 1) {
    const q: V3[] = [];
    for (let i = 0; i < p.length; i += 1) {
      const a = p[i]!;
      const b = p[(i + 1) % p.length]!;
      q.push([0.75 * a[0] + 0.25 * b[0], 0.75 * a[1] + 0.25 * b[1], 0.75 * a[2] + 0.25 * b[2]]);
      q.push([0.25 * a[0] + 0.75 * b[0], 0.25 * a[1] + 0.75 * b[1], 0.25 * a[2] + 0.75 * b[2]]);
    }
    p = q;
  }
  return p;
};

const finish = (pts: V3[], closed: boolean): Curve => {
  const all = closed ? [...pts, pts[0]!] : pts;
  const len = [0];
  for (let i = 1; i < all.length; i += 1) {
    const a = all[i - 1]!;
    const b = all[i]!;
    len.push(len[i - 1]! + Math.hypot(b[0] - a[0], b[1] - a[1], b[2] - a[2]));
  }
  return { pts: all, len, total: len[len.length - 1]!, closed };
};

/** `size` is the half width of the shape in world px; `depth` is how far the line swings in z. */
export const makeCurve = (shape: PathShape, size: number, depth: number): Curve => {
  if (shape === 'wave') {
    const pts: V3[] = [];
    const n = 240;
    for (let i = 0; i <= n; i += 1) {
      const u = i / n;
      pts.push([(u - 0.5) * 2 * size * 1.5, Math.sin(u * Math.PI * 2 * 1.1 + 0.4) * size * 0.28, Math.cos(u * Math.PI * 2 * 1.1 + 0.4) * depth]);
    }
    return finish(pts, false);
  }
  if (shape === 'triangle') {
    const r = size * 0.78;
    const tri: V3[] = [[0, -r, 0], [r * 0.9, r * 0.62, 0], [-r * 0.9, r * 0.62, 0]];
    return finish(chaikin(tri, 4), true);
  }
  if (shape === 'square') {
    const w = size * 0.82;
    const h = size * 0.56;
    return finish(chaikin([[-w, -h, 0], [w, -h, 0], [w, h, 0], [-w, h, 0]], 4), true);
  }
  const pts: V3[] = [];
  const n = 280;
  for (let i = 0; i < n; i += 1) {
    const t = (i / n) * Math.PI * 2;
    const k = 1 + Math.sin(t) ** 2;
    pts.push([(size * 1.05 * Math.cos(t)) / k, (size * 1.05 * Math.sin(t) * Math.cos(t)) / k * 1.25, Math.sin(t) * depth]);
  }
  return finish(pts, true);
};

/** The point at fraction `u` of the length (wrapped for a closed curve, clamped for an open one) and its direction. */
export const sample = (c: Curve, u: number): { p: V3; t: V3 } => {
  const uu = c.closed ? ((u % 1) + 1) % 1 : Math.min(1, Math.max(0, u));
  const d = uu * c.total;
  let lo = 0;
  let hi = c.len.length - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (c.len[mid]! <= d) lo = mid;
    else hi = mid;
  }
  const a = c.pts[lo]!;
  const b = c.pts[hi]!;
  const seg = c.len[hi]! - c.len[lo]! || 1;
  const k = (d - c.len[lo]!) / seg;
  const t: V3 = [(b[0] - a[0]) / seg, (b[1] - a[1]) / seg, (b[2] - a[2]) / seg];
  return { p: [a[0] + (b[0] - a[0]) * k, a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k], t };
};

// Path-orient: cards ride a rounded triangle and turn to its tangent, so each swings through the corners like a car on
// a track. The camera chases the lead card low and close, banking with it through the corner (yaw follows the heading), holds on it with the focus landing, then cranes up and out in one motion-blurred move to the tilted view of the whole loop and settles with the focus still on the leader.
//
// Principles: arcs and follow-through (the turn at a corner is the path's own curve, and the cards behind turn later),
// overlap (the leader leaves first), slow in and slow out, staging, solid drawing.

import React from 'react';
import { z } from 'zod';
import { useCurrentFrame } from '@kinetographdev/core';
import { Stage, camDrift, commonDefaults, commonShape, lerp, projectPoint, ramp, shutterFor, themeOf, type Cam, type V3 } from './kit.js';
import { makeCurve, PATH_SHAPES } from './curves.js';
import { buildTrain, PathLine } from './train.js';

export const pathOrientSchema = z.object({
  ...commonShape,
  shape: z.enum(PATH_SHAPES as [string, ...string[]]).describe('The curve the cards follow.'),
  count: z.number().int().min(3).max(24).describe('Cards on the path.'),
  size: z.number().min(300).max(1600).describe('Half width of the curve, world px.'),
  cardWidth: z.number().min(60).max(600).describe('Card width, world px.'),
  cardHeight: z.number().min(60).max(700).describe('Card height, world px.'),
  turns: z.number().min(0.1).max(3).describe('Slots the train advances in the move (1 = one card position).'),
  follow: z.number().min(0).max(1).describe('How far each card turns to the tangent: 0 keeps it upright, 1 follows the path fully.'),
  lag: z.number().min(0).max(8).describe('Frames each card sets off after the one ahead.'),
  showLine: z.boolean().describe('Draw the path as a hairline under the cards. Off by default.'),
  orbit: z.number().min(0).max(50).describe('Degrees the camera turns about the path.'),
  distance: z.number().min(600).max(6000).describe('Eye distance of the wide shot after the crane.'),
  chaseDistance: z.number().min(300).max(3000).describe('Eye distance while chasing the lead card.'),
  motionBlur: z.number().min(0).max(1).describe('Camera motion blur shutter in frames, used while the camera moves fast. 0 turns it off.'),
});
export type PathOrientProps = z.infer<typeof pathOrientSchema>;

export const pathOrientDefaults: PathOrientProps = {
  ...commonDefaults,
  caption: 'Path orient',
  shape: 'triangle',
  count: 9,
  size: 1500,
  cardWidth: 320,
  cardHeight: 240,
  turns: 1.5,
  follow: 1,
  lag: 2,
  showLine: false,
  orbit: 22,
  distance: 2550,
  chaseDistance: 1150,
  motionBlur: 0,
};

export const PATH_ORIENT_DURATION = 240;

const io = (x: number) => (x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2);

export const PathOrient: React.FC<Partial<PathOrientProps>> = (partial) => {
  const p = { ...pathOrientDefaults, ...partial };
  const f = useCurrentFrame();
  const curve = makeCurve(p.shape as 'triangle', p.size, 160);
  const train = (t: number) =>
    buildTrain(t, {
      curve, count: p.count, cardWidth: p.cardWidth, cardHeight: p.cardHeight, travel: curve.closed ? p.turns / p.count : 0.3,
      start: 30, lag: p.lag, span: 140, follow: p.follow, offsetDeg: 0,
    });
  const items = train(f);
  const leadPos = (t: number): V3 => train(t)[p.count - 1]!.pos;
  const craneA = 112;
  const craneB = 168;
  const camAt = (t: number): Cam => {
    const c = ramp(t, craneA, craneB, io);
    const over = 1 + 0.04 * Math.sin(ramp(t, craneB - 8, craneB + 26, (x) => x) * Math.PI) * (t > craneB - 8 ? 1 : 0);
    const dip = Math.sin(ramp(t, craneA - 16, craneA, (x) => x) * Math.PI) * (t < craneA ? 1 : 0);
    const a = leadPos(t - 3);
    const b = leadPos(t + 3);
    const lead = leadPos(t);
    // the heading of the leader: the camera banks and yaws with it through the corner
    const heading = (Math.atan2(b[1] - a[1], b[0] - a[0]) * 180) / Math.PI;
    const tgt: V3 = [lerp(lead[0], 0, c), lerp(lead[1], 20, c), 0];
    return {
      yaw: lerp(-8 + 0.18 * heading, -6, c),
      pitch: lerp(-6, -24, c) + dip * 2.5,
      roll: lerp(-0.12 * heading, 0, c),
      dist: lerp(p.chaseDistance, p.distance, c) * over + dip * 70,
      focal: 1700,
      target: tgt,
      pan: [0, 0],
    };
  };
  const dd = camDrift(f, p.drift * 0.6);
  const cam = camAt(f);
  cam.yaw += dd.yaw;
  cam.roll += dd.roll;
  cam.pan = dd.pan;
  // the leader is the subject, sharp from start to end
  const focus = projectPoint(leadPos(f), cam).dist;
  const shutter = p.motionBlur > 0 ? shutterFor(camAt, f, [leadPos(f), [0, 0, 0], [p.size * 0.6, 0, 0]], 8, p.motionBlur) : 0;
  const theme = themeOf(p.colors);
  return (
    <Stage
      cam={cam}
      items={items}
      photos={p.photos}
      look={{ focus, aperture: p.aperture, fogStart: cam.dist * 1.1, fogLen: cam.dist * 0.8, fogMax: 0.5, radius: p.radius }}
      theme={theme}
      hud={{ caption: p.caption, showHud: p.showHud }}
      shutter={shutter}
      under={p.showLine ? <PathLine curve={curve} cam={cam} f={f} a={0} b={44} color={theme.ink} /> : null}
    />
  );
};

// What the eight arrangements share: a small 3D layout engine (hand projection, so a frame is a pure function of the
// frame number and the camera can go anywhere), the photo card, the stage (ground, depth of field, fog, grain, a quiet
// caption) and the timing helpers.
//
// The engine places each card by hand: a card's centre is projected with a perspective camera (position and scale at
// that depth), and its tilt is the layer's own rotateX / rotateY / rotation, seen through a scene `<Camera>` whose
// perspective is the same focal length, so a tilted card foreshortens exactly as the projection says it should.
// Cards are drawn far to near.

import React from 'react';
import { z } from 'zod';
import { Camera, Image, Layer, Rect, Text, blur, grain, radialGradient, staticFile, useCurrentFrame } from '@kinetographdev/core';
import { loadFont } from '@remotion/google-fonts/Geist';

export const W = 1920;
export const H = 1080;
export const FPS = 30;

export const FONT = loadFont('normal', { weights: ['400'] }).fontFamily;

// ---- timing ---------------------------------------------------------------------------------------------------

export const clamp = (v: number, a = 0, b = 1) => Math.min(b, Math.max(a, v));
export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;
/** Slow in, slow out. */
export const inOut = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2);
/** Quick start, long settle. */
export const out = (t: number) => 1 - Math.pow(1 - t, 3);
export const outQuint = (t: number) => 1 - Math.pow(1 - t, 5);
export const inCubic = (t: number) => t * t * t;
/** A settle that overshoots by about 4% and comes back. */
export const outBack = (t: number) => {
  const c1 = 1.1;
  const c3 = c1 + 1;
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
};
/** 0 before `a`, 1 after `b`, `ease` between. */
export const ramp = (f: number, a: number, b: number, ease: (t: number) => number = inOut) => ease(clamp((f - a) / Math.max(1e-6, b - a)));
/** Pose-to-pose keys: [frame, value] pairs, each segment eased slow in and slow out, so the value rests at every key. */
export const track = (f: number, keys: [number, number][], ease: (t: number) => number = inOut): number => {
  if (f <= keys[0]![0]) return keys[0]![1];
  for (let i = 1; i < keys.length; i += 1) {
    const [f1, v1] = keys[i]!;
    if (f <= f1) {
      const [f0, v0] = keys[i - 1]!;
      return lerp(v0, v1, ease((f - f0) / (f1 - f0)));
    }
  }
  return keys[keys.length - 1]![1];
};
/** Straight-ahead life on a long hold: a few slow sines, `amp` in the unit of the value. The phases come from `seed`. */
export const drift = (f: number, amp: number, seed: number) =>
  amp * (0.55 * Math.sin(f * 0.043 + seed * 2.1) + 0.3 * Math.sin(f * 0.091 + seed * 5.3) + 0.15 * Math.sin(f * 0.17 + seed * 1.7));

// ---- 3D -------------------------------------------------------------------------------------------------------

export type V3 = [number, number, number];
/** Row-major 3x3. Axes as CSS: x right, y down, z toward the viewer. */
export type M3 = [number, number, number, number, number, number, number, number, number];
const rad = (d: number) => (d * Math.PI) / 180;
const deg = (r: number) => (r * 180) / Math.PI;

export const I3: M3 = [1, 0, 0, 0, 1, 0, 0, 0, 1];
export const rotX = (d: number): M3 => {
  const c = Math.cos(rad(d));
  const s = Math.sin(rad(d));
  return [1, 0, 0, 0, c, -s, 0, s, c];
};
export const rotY = (d: number): M3 => {
  const c = Math.cos(rad(d));
  const s = Math.sin(rad(d));
  return [c, 0, s, 0, 1, 0, -s, 0, c];
};
/** Clockwise on screen. */
export const rotZ = (d: number): M3 => {
  const c = Math.cos(rad(d));
  const s = Math.sin(rad(d));
  return [c, -s, 0, s, c, 0, 0, 0, 1];
};
export const mul = (a: M3, b: M3): M3 => {
  const r = new Array<number>(9).fill(0);
  for (let i = 0; i < 3; i += 1) for (let j = 0; j < 3; j += 1) for (let k = 0; k < 3; k += 1) r[i * 3 + j]! += a[i * 3 + k]! * b[k * 3 + j]!;
  return r as M3;
};
export const transpose = (m: M3): M3 => [m[0], m[3], m[6], m[1], m[4], m[7], m[2], m[5], m[8]];
export const apply = (m: M3, v: V3): V3 => [
  m[0] * v[0] + m[1] * v[1] + m[2] * v[2],
  m[3] * v[0] + m[4] * v[1] + m[5] * v[2],
  m[6] * v[0] + m[7] * v[1] + m[8] * v[2],
];

export interface Cam {
  /** Degrees. Turns the world about the vertical axis through `target`: the orbit. */
  yaw: number;
  /** Degrees. Positive tips the near side up (looks up from below); negative looks down on the scene. */
  pitch: number;
  /** Degrees, clockwise. */
  roll: number;
  /** Eye to `target`, in world units. With `focal` equal to it, the target plane is drawn at 1:1. */
  dist: number;
  focal: number;
  target: V3;
  /** Pixels the frame is shifted on screen after projection (a truck without parallax). */
  pan?: [number, number];
}

export const camMatrix = (c: Cam): M3 => mul(rotZ(c.roll), mul(rotX(c.pitch), rotY(c.yaw)));

export interface Item {
  key: number | string;
  pos: V3;
  /** Card to world. Identity: upright, facing +z. `'camera'`: always facing the screen. */
  orient?: M3 | 'camera';
  /** With `'camera'`, a turn in the card's own plane, degrees. */
  spin?: number;
  photo: number;
  w: number;
  h: number;
  opacity?: number;
  scale?: number;
  /** 0..1 extra darkening. */
  shade?: number;
  /** Draw only while the face is turned toward the eye (a card drawn twice, one face each way, is double sided). */
  cull?: boolean;
  /** The number the counter shows for this card (defaults to the key). */
  n?: number;
}

export interface Look {
  /** Distance (eye to card) that is in focus, world units; `'auto'` follows the cards near the middle of the frame. */
  focus: number | 'auto';
  /** Blur in px of a card one `focus` away from the focus plane; 0 for none. */
  aperture: number;
  /** Eye distance where the fog starts and how long it takes to reach `fogMax`. */
  fogStart: number;
  fogLen: number;
  fogMax: number;
  /** Corner radius of the card, px at 1:1. */
  radius: number;
  /** Cards closer to the eye than this fade out (an eye that passes through them). 0 for none. */
  near?: number;
}

export const rrPath = (w: number, h: number, r: number) => {
  const k = Math.min(r, w / 2, h / 2);
  return `M${k} 0H${w - k}Q${w} 0 ${w} ${k}V${h - k}Q${w} ${h} ${w - k} ${h}H${k}Q0 ${h} 0 ${h - k}V${k}Q0 0 ${k} 0Z`;
};

/** One photo, cover-fitted, with a shade, and a hairline edge only if `edge` is set (not 'none'). */
export const PhotoCard: React.FC<{ src: string; w: number; h: number; radius: number; shade: number; edge: string }> = ({ src, w, h, radius, shade, edge }) => (
  <>
    <Image src={src} width={w} height={h} fit="cover" clip={{ kind: 'path', d: rrPath(w, h, radius) }} />
    {shade > 0.01 ? <Rect width={w} height={h} radius={radius} fill="#040507" opacity={clamp(shade)} /> : null}
    {edge && edge !== 'none' ? <Rect width={w} height={h} radius={radius} stroke={{ color: edge, width: 1.5 }} /> : null}
  </>
);

const photoSrc = (photos: string[], i: number) => staticFile(`photos/${photos[((i % photos.length) + photos.length) % photos.length]}`);

export interface Placed {
  item: Item;
  sx: number;
  sy: number;
  s: number;
  dist: number;
  rx: number;
  ry: number;
  rz: number;
  front: boolean;
}

/** Project items through `cam`: where each lands, how big, how it is turned, and whether you see its face. */
export const project = (items: Item[], cam: Cam): Placed[] => {
  const R = camMatrix(cam);
  const out: Placed[] = [];
  for (const item of items) {
    const q = apply(R, [item.pos[0] - cam.target[0], item.pos[1] - cam.target[1], item.pos[2] - cam.target[2]]);
    const dist = cam.dist - q[2];
    if (dist < 60) continue;
    const s = cam.focal / dist;
    const sx = W / 2 + q[0] * s + (cam.pan?.[0] ?? 0);
    const sy = H / 2 + q[1] * s + (cam.pan?.[1] ?? 0);
    // the card in camera space
    const M: M3 = item.orient === 'camera' ? rotZ(item.spin ?? 0) : mul(R, item.orient ?? I3);
    const m02 = clamp(M[2], -1, 1);
    const b = Math.asin(m02);
    const cb = Math.cos(b);
    let a: number;
    let c: number;
    if (cb > 1e-4) {
      a = Math.atan2(-M[5], M[8]);
      c = Math.atan2(-M[1], M[0]);
    } else {
      a = 0;
      c = Math.atan2(M[3], M[4]);
    }
    // normal (third column) against the way to the eye
    const n: V3 = [M[2], M[5], M[8]];
    const toEye: V3 = [-q[0], -q[1], cam.dist - q[2]];
    const front = n[0] * toEye[0] + n[1] * toEye[1] + n[2] * toEye[2] > 0;
    out.push({ item, sx, sy, s, dist, rx: deg(a), ry: deg(b), rz: deg(c), front });
  }
  return out.sort((p, q) => q.dist - p.dist);
};

/** Where a world point lands on screen. */
export const projectPoint = (pos: V3, cam: Cam): { x: number; y: number; s: number; dist: number } => {
  const q = apply(camMatrix(cam), [pos[0] - cam.target[0], pos[1] - cam.target[1], pos[2] - cam.target[2]]);
  const dist = Math.max(60, cam.dist - q[2]);
  const s = cam.focal / dist;
  return { x: W / 2 + q[0] * s + (cam.pan?.[0] ?? 0), y: H / 2 + q[1] * s + (cam.pan?.[1] ?? 0), s, dist };
};

export interface Theme {
  ground: string;
  ground2: string;
  ink: string;
  edge: string;
}

export const THEME: Theme = { ground: '#0a0b0d', ground2: '#171a1f', ink: '#e9e6df', edge: 'none' };

export interface HudProps {
  caption: string;
  showHud: boolean;
}

/** The stage: ground, cards far to near with depth of field and fog, a quiet caption and a little grain. */
export const Stage: React.FC<{
  cam: Cam;
  items: Item[];
  photos: string[];
  look: Look;
  theme: Theme;
  hud: HudProps;
  /** 0..1 fade of the whole frame in and out. */
  fade?: number;
  /** Drawn under the cards, over the ground (a path line, say). */
  under?: React.ReactNode;
  grainAmount?: number;
  /** Shutter in frames for camera motion blur (0 or undefined: off). */
  shutter?: number;
  /** Number of cards the counter names (defaults to the item count). */
  total?: number;
}> = ({ cam, items, photos, look, theme, hud, fade = 1, under, grainAmount = 0.03, shutter = 0, total }) => {
  const placed = project(items, cam);
  // the card nearest the middle of the frame is the one the counter names
  let near: Placed | undefined;
  let best = 1e9;
  for (const p of placed) {
    if ((p.item.opacity ?? 1) < 0.6 || !p.front || p.dist < 120) continue;
    const d = Math.hypot(p.sx - W / 2, (p.sy - H / 2) * 1.2) / p.s;
    if (d < best) { best = d; near = p; }
  }
  let focusDist = typeof look.focus === 'number' ? look.focus : cam.dist;
  if (look.focus === 'auto') {
    let wsum = 0;
    let dsum = 0;
    for (const p of placed) {
      if ((p.item.opacity ?? 1) < 0.3) continue;
      const d2 = (p.sx - W / 2) ** 2 + (p.sy - H / 2) ** 2;
      const w = Math.exp(-d2 / (2 * 330 * 330));
      wsum += w;
      dsum += w * p.dist;
    }
    if (wsum > 1e-3) focusDist = dsum / wsum;
  }
  const counter = near ? `${pad2((near.item.n ?? Number(near.item.key)) + 1)} / ${pad2(total ?? items.length)}` : '';
  return (
    <Layer id="shutter" motionBlur={shutter > 0 ? { samples: 8, shutter } : undefined}>
    <Layer id="stage" effects={grainAmount > 0 ? [grain(grainAmount, { seed: 11, size: 1.3, animate: true, monochrome: true })] : []}>
      <Rect id="ground" width={W} height={H} fill={radialGradient([[0, theme.ground2], [1, theme.ground]], { cx: 0.5, cy: 0.46, r: 0.75 })} />
      {under}
      <Camera perspective={cam.focal} />
      <Layer id="cards" opacity={fade}>
        {placed.map((p) => {
          const { item } = p;
          const sc = p.s * (item.scale ?? 1);
          if (item.cull && !p.front) return null;
          const nearFade = look.near ? clamp((p.dist - look.near * 0.5) / (look.near * 0.5)) : 1;
          if (sc <= 0.002 || (item.opacity ?? 1) * nearFade <= 0.002) return null;
          const fog = look.fogLen > 0 ? clamp((p.dist - look.fogStart) / look.fogLen) * look.fogMax : 0;
          const shade = clamp(Math.max(fog, item.shade ?? 0) + (p.front || item.cull ? 0 : 0.5));
          const coc = look.aperture > 0 ? (look.aperture * Math.abs(p.dist - focusDist)) / focusDist : 0;
          const r = Math.round(coc * 2) / 2;
          return (
            <Layer
              key={item.key}
              id={`c${item.key}`}
              x={p.sx}
              y={p.sy}
              anchorX={item.w / 2}
              anchorY={item.h / 2}
              scale={sc}
              rotateX={p.rx}
              rotateY={p.ry}
              rotation={p.rz}
              opacity={(item.opacity ?? 1) * nearFade}
              effects={r >= 1 ? [blur(Math.min(r, 28) / Math.max(sc, 0.2))] : []}
            >
              <PhotoCard src={photoSrc(photos, item.photo)} w={item.w} h={item.h} radius={look.radius} shade={shade} edge={theme.edge} />
            </Layer>
          );
        })}
      </Layer>
      {hud.showHud ? <Hud caption={hud.caption} counter={counter} theme={theme} fade={fade} /> : null}
    </Layer>
    </Layer>
  );
};

const Hud: React.FC<{ caption: string; counter: string; theme: Theme; fade: number }> = ({ caption, counter, theme, fade }) => (
  <Layer id="hud" opacity={0.62 * fade}>
